#!/usr/bin/env python3
"""Convert owned raw generated sources while preserving their physical lines.

Start from the preserved legacy source, not v1/v2 output. New header commands
share existing header lines. Sail.BitVec meta-scope markers occupy existing
blank lines. No runtime expression or macro pattern/result is rewritten.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re

I7_BANNERS = {
    "Sail/ConcurrencyInterfaceV1.lean": "-- GENERATED by tools/isaw/gen_shape_family.py from ConcurrencyInterfaceV1.json. Do not edit: change the templates / data.",
    "Sail/AbstractRealRat.lean": "-- GENERATED by tools/isaw/gen_shape_family.py from AbstractRealRat.json. Do not edit: change the templates / data.",
}


def once(source, old, new):
    if source.count(old) != 1:
        raise ValueError("unexpected raw source layout: " + repr(old))
    return source.replace(old, new, 1)


def transform(source, role, rel, meta_imports=()):
    if re.search(r"^module\b", source, re.M):
        raise ValueError("raw legacy source required: " + rel)
    for name in meta_imports:
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", name):
            raise ValueError("invalid meta import")
    head = "public section" if role == "interface" else "set_option backward.proofsInPublic true @[expose] public section"
    imports = list(meta_imports)
    if rel == "Sail/Attr.lean":
        # Model-header residual (boss 02:02Z): keep the two private `initialize` helpers (initFn) in the public
        # export like the legacy model; file-local, changes no other constant's kind or visibility.
        head = head.replace("set_option backward.proofsInPublic true",
                            "set_option backward.proofsInPublic true set_option backward.privateInPublic true", 1)
    if rel == "Sail/BitVec.lean":
        if "Lean" not in imports:
            imports.append("Lean")
        head += " meta section"
    extra = "".join("public meta import " + name + " " for name in dict.fromkeys(imports))
    # The approved I7 removal occupies its old line with `module`, rather than
    # deleting a line and changing runtime/quotation source positions.
    prefix = "module "
    raw = source
    if rel in I7_BANNERS:
        banner = I7_BANNERS[rel] + "\n"
        if not raw.startswith(banner):
            raise ValueError("expected immutable pre-I7 banner: " + rel)
        raw = raw[len(banner):]
        prefix = "module\n"
    result = re.sub(r"^import ", "public import ", raw, flags=re.M)
    matches = list(re.finditer(r"^public import [^\n]+", result, re.M))
    if matches:
        position = matches[-1].end()
        result = prefix + result[:position] + " " + extra + head + result[position:]
    else:
        result = prefix + extra + head + " " + result
    if rel == "Sail/BitVec.lean":
        result = once(result, "\n\n-- We use this to gather", "\nend\n-- We use this to gather")
        result = once(result, "\n\n@[term_elab matchBv]",
                      "\nmeta section open Lean Elab Term open BitVec\n@[term_elab matchBv]")
    if source.count("\n") != result.count("\n"):
        raise ValueError("physical line count changed")
    return result


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("root", type=Path)
    ap.add_argument("--interface", action="append", default=[])
    ap.add_argument("--meta-import", action="append", default=[], metavar="RELATIVE_FILE=MODULE")
    ap.add_argument("--manifest", type=Path, required=True)
    a = ap.parse_args()
    root = a.root.resolve(strict=True)
    extra = {}
    for entry in a.meta_import:
        rel, name = entry.split("=", 1)
        extra.setdefault(rel, []).append(name)
    files = {}
    for stem, role in (("Sail", "runtime"), ("ArmFull", "model")):
        for p in [root / (stem + ".lean"), *sorted((root / stem).rglob("*.lean"))]:
            if p.is_file():
                files[p] = role
    for rel in a.interface:
        p = (root / rel).resolve(strict=True)
        p.relative_to(root)
        files[p] = "interface"
    known = {p.relative_to(root).as_posix() for p in files}
    if set(extra) - known:
        raise ValueError("meta import target is outside the selected source set")
    pending = []
    for p, role in sorted(files.items()):
        p.resolve(strict=True).relative_to(root)
        rel = p.relative_to(root).as_posix()
        before = p.read_bytes()
        after = transform(before.decode(), role, rel, extra.get(rel, ())).encode()
        pending.append((p, after, {"path": rel, "role": role,
                        "before_sha256": hashlib.sha256(before).hexdigest(),
                        "after_sha256": hashlib.sha256(after).hexdigest(),
                        "line_count_unchanged": True, "i7_banner_line_reused": rel in I7_BANNERS,
                        "meta_imports": extra.get(rel, [])}))
    if not pending:
        raise ValueError("empty source set")
    for p, data, _ in pending:
        p.write_bytes(data)
    report = {"schema": "line-preserving-module-postpass-v1",
              "tool_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              "files": [row[2] for row in pending], "input": "preserved raw legacy sources",
              "semantic_acceptance": "requires exact full export/body/private/scope comparison"}
    a.manifest.parent.mkdir(parents=True, exist_ok=True)
    a.manifest.write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps({"files": len(pending)}))


if __name__ == "__main__":
    main()
